begin;

alter table public.questions drop constraint if exists questions_question_type_check;
alter table public.questions add constraint questions_question_type_check
  check (question_type in ('multiple_choice', 'fill_blank', 'listening', 'word_order'));

insert into public.lessons (
  level_id, slug, title, description, category, duration_minutes, sort_order, is_published
)
select levels.id, lesson.slug, lesson.title, lesson.description, lesson.category,
  lesson.duration_minutes, lesson.sort_order, lesson.is_published
from public.language_levels as levels
join public.languages on languages.id = levels.language_id
join (
  values
    ('organize-a1', 'A1', 'Organize as palavras · A1', 'Monte frases reais e veja como cada palavra ocupa seu lugar.', 'Construção de frases', 12, 50, true),
    ('organize-a2', 'A2', 'Organize as palavras · A2', 'Monte frases reais e veja como cada palavra ocupa seu lugar.', 'Construção de frases', 12, 50, true),
    ('organize-b1', 'B1', 'Organize as palavras · B1', 'Monte frases reais e veja como cada palavra ocupa seu lugar.', 'Construção de frases', 12, 50, true),
    ('organize-b2', 'B2', 'Organize as palavras · B2', 'Monte frases reais e veja como cada palavra ocupa seu lugar.', 'Construção de frases', 12, 50, true),
    ('organize-c1', 'C1', 'Organize as palavras · C1', 'Monte frases reais e veja como cada palavra ocupa seu lugar.', 'Construção de frases', 12, 50, true),
    ('organize-c2', 'C2', 'Organize as palavras · C2', 'Monte frases reais e veja como cada palavra ocupa seu lugar.', 'Construção de frases', 12, 50, true)
) as lesson(slug, level_code, title, description, category, duration_minutes, sort_order, is_published)
  on lesson.level_code = levels.code
where languages.code = 'en'
on conflict (slug) do update set
  title = excluded.title,
  description = excluded.description,
  category = excluded.category,
  duration_minutes = excluded.duration_minutes,
  sort_order = excluded.sort_order,
  is_published = excluded.is_published;

with word_questions(level_code, question_order, prompt, words, answer, explanation, hint) as (
  values
    ('A1', 1, 'Organize as palavras para formar uma frase: "I am a student."', ARRAY['I', 'am', 'a', 'student']::text[], 'I am a student', 'A ordem correta é "I am a student.".', 'Use am com I para falar de identidade, profissão e estado.'),
    ('A1', 2, 'Organize as palavras para formar uma frase: "My name is Ana."', ARRAY['My', 'name', 'is', 'Ana']::text[], 'My name is Ana', 'A ordem correta é "My name is Ana.".', 'Use is com nomes e com he, she e it.'),
    ('A1', 3, 'Organize as palavras para formar uma frase: "You are my friend."', ARRAY['You', 'are', 'my', 'friend']::text[], 'You are my friend', 'A ordem correta é "You are my friend.".', 'Use are com you, we e they.'),
    ('A1', 4, 'Organize as palavras para formar uma frase: "This is my house."', ARRAY['This', 'is', 'my', 'house']::text[], 'This is my house', 'A ordem correta é "This is my house.".', 'Use This is para apresentar algo perto de você.'),
    ('A1', 5, 'Organize as palavras para formar uma frase: "I have a dog."', ARRAY['I', 'have', 'a', 'dog']::text[], 'I have a dog', 'A ordem correta é "I have a dog.".', 'Use have para falar que você possui algo.'),
    ('A1', 6, 'Organize as palavras para formar uma frase: "She likes music."', ARRAY['She', 'likes', 'music']::text[], 'She likes music', 'A ordem correta é "She likes music.".', 'Com he, she e it, o verbo no presente geralmente recebe s.'),
    ('A1', 7, 'Organize as palavras para formar uma frase: "He works at home."', ARRAY['He', 'works', 'at', 'home']::text[], 'He works at home', 'A ordem correta é "He works at home.".', 'Use works com he; at home indica o local da atividade.'),
    ('A1', 8, 'Organize as palavras para formar uma frase: "We live in Brazil."', ARRAY['We', 'live', 'in', 'Brazil']::text[], 'We live in Brazil', 'A ordem correta é "We live in Brazil.".', 'Use live in para falar onde alguém mora.'),
    ('A1', 9, 'Organize as palavras para formar uma frase: "What is your name."', ARRAY['What', 'is', 'your', 'name']::text[], 'What is your name', 'A ordem correta é "What is your name.".', 'What is your name? é uma pergunta básica para conhecer alguém.'),
    ('A1', 10, 'Organize as palavras para formar uma frase: "How are you today."', ARRAY['How', 'are', 'you', 'today']::text[], 'How are you today', 'A ordem correta é "How are you today.".', 'How are you? pergunta como a pessoa está.'),
    ('A1', 11, 'Organize as palavras para formar uma frase: "I like English."', ARRAY['I', 'like', 'English']::text[], 'I like English', 'A ordem correta é "I like English.".', 'Use like para falar de preferências.'),
    ('A1', 12, 'Organize as palavras para formar uma frase: "She is from Spain."', ARRAY['She', 'is', 'from', 'Spain']::text[], 'She is from Spain', 'A ordem correta é "She is from Spain.".', 'Use is from para falar de origem.'),
    ('A1', 13, 'Organize as palavras para formar uma frase: "They are at school."', ARRAY['They', 'are', 'at', 'school']::text[], 'They are at school', 'A ordem correta é "They are at school.".', 'Use at para indicar um ponto ou lugar específico.'),
    ('A1', 14, 'Organize as palavras para formar uma frase: "It is sunny today."', ARRAY['It', 'is', 'sunny', 'today']::text[], 'It is sunny today', 'A ordem correta é "It is sunny today.".', 'Use it is para falar sobre o clima.'),
    ('A1', 15, 'Organize as palavras para formar uma frase: "I wake up early."', ARRAY['I', 'wake', 'up', 'early']::text[], 'I wake up early', 'A ordem correta é "I wake up early.".', 'Wake up significa acordar; early significa cedo.'),
    ('A1', 16, 'Organize as palavras para formar uma frase: "He drinks water."', ARRAY['He', 'drinks', 'water']::text[], 'He drinks water', 'A ordem correta é "He drinks water.".', 'Com he, drink vira drinks no presente.'),
    ('A1', 17, 'Organize as palavras para formar uma frase: "Can I have water."', ARRAY['Can', 'I', 'have', 'water']::text[], 'Can I have water', 'A ordem correta é "Can I have water.".', 'Can I have...? é uma forma educada de pedir algo.'),
    ('A1', 18, 'Organize as palavras para formar uma frase: "See you tomorrow."', ARRAY['See', 'you', 'tomorrow']::text[], 'See you tomorrow', 'A ordem correta é "See you tomorrow.".', 'See you é uma despedida; troque tomorrow por later ou soon.'),
    ('A1', 19, 'Organize as palavras para formar uma frase: "There is a book."', ARRAY['There', 'is', 'a', 'book']::text[], 'There is a book', 'A ordem correta é "There is a book.".', 'There is apresenta uma coisa no singular.'),
    ('A1', 20, 'Organize as palavras para formar uma frase: "I do not understand."', ARRAY['I', 'do', 'not', 'understand']::text[], 'I do not understand', 'A ordem correta é "I do not understand.".', 'Do not cria a negativa com I, you, we e they.'),
    ('A2', 1, 'Organize as palavras para formar uma frase: "I went to the market."', ARRAY['I', 'went', 'to', 'the', 'market']::text[], 'I went to the market', 'A ordem correta é "I went to the market.".', 'Went é o passado de go; use para ações concluídas.'),
    ('A2', 2, 'Organize as palavras para formar uma frase: "She watched a movie."', ARRAY['She', 'watched', 'a', 'movie']::text[], 'She watched a movie', 'A ordem correta é "She watched a movie.".', 'No passado regular, watch vira watched.'),
    ('A2', 3, 'Organize as palavras para formar uma frase: "Could you help me."', ARRAY['Could', 'you', 'help', 'me']::text[], 'Could you help me', 'A ordem correta é "Could you help me.".', 'Could you...? faz pedidos educados.'),
    ('A2', 4, 'Organize as palavras para formar uma frase: "I would like some coffee."', ARRAY['I', 'would', 'like', 'some', 'coffee']::text[], 'I would like some coffee', 'A ordem correta é "I would like some coffee.".', 'I would like é útil para pedidos e preferências.'),
    ('A2', 5, 'Organize as palavras para formar uma frase: "We are going to travel."', ARRAY['We', 'are', 'going', 'to', 'travel']::text[], 'We are going to travel', 'A ordem correta é "We are going to travel.".', 'Be going to fala de planos futuros.'),
