    ('A2', 9, 'Organize as palavras para formar uma frase: "Have you ever been there."', ARRAY['Have', 'you', 'ever', 'been', 'there']::text[], 'Have you ever been there', 'A ordem correta é "Have you ever been there.".', 'Have you ever...? pergunta sobre experiências.'),
