    ('A2', 11, 'Organize as palavras para formar uma frase: "How much does it cost."', ARRAY['How', 'much', 'does', 'it', 'cost']::text[], 'How much does it cost', 'A ordem correta é "How much does it cost.".', 'How much...? pergunta o preço de algo.'),
    ('A2', 12, 'Organize as palavras para formar uma frase: "There are two chairs."', ARRAY['There', 'are', 'two', 'chairs']::text[], 'There are two chairs', 'A ordem correta é "There are two chairs.".', 'There are apresenta várias coisas.'),
    ('A2', 13, 'Organize as palavras para formar uma frase: "I have to leave now."', ARRAY['I', 'have', 'to', 'leave', 'now']::text[], 'I have to leave now', 'A ordem correta é "I have to leave now.".', 'Have to expressa necessidade ou obrigação.'),
    ('A2', 14, 'Organize as palavras para formar uma frase: "You should get some rest."', ARRAY['You', 'should', 'get', 'some', 'rest']::text[], 'You should get some rest', 'A ordem correta é "You should get some rest.".', 'Should dá conselhos.'),
