    ('A2', 16, 'Organize as palavras para formar uma frase: "She has been working all day."', ARRAY['She', 'has', 'been', 'working', 'all', 'day']::text[], 'She has been working all day', 'A ordem correta é "She has been working all day.".', 'Present perfect continuous destaca duração até agora.'),
    ('A2', 17, 'Organize as palavras para formar uma frase: "We missed the bus."', ARRAY['We', 'missed', 'the', 'bus']::text[], 'We missed the bus', 'A ordem correta é "We missed the bus.".', 'Missed significa perdeu; use também para encontros ou pessoas.'),
