    ('A2', 19, 'Organize as palavras para formar uma frase: "It depends on the weather."', ARRAY['It', 'depends', 'on', 'the', 'weather']::text[], 'It depends on the weather', 'A ordem correta é "It depends on the weather.".', 'It depends on... significa depende de algo.'),
    ('A2', 20, 'Organize as palavras para formar uma frase: "I am interested in art."', ARRAY['I', 'am', 'interested', 'in', 'art']::text[], 'I am interested in art', 'A ordem correta é "I am interested in art.".', 'Interested in é seguido por substantivo ou verbo com -ing.'),
