    ('B2', 8, 'Organize as palavras para formar uma frase: "I would have preferred to stay longer."', ARRAY['I', 'would', 'have', 'preferred', 'to', 'stay', 'longer']::text[], 'I would have preferred to stay longer', 'A ordem correta é "I would have preferred to stay longer.".', 'Would have preferred fala de uma preferência não realizada.'),
    ('B2', 9, 'Organize as palavras para formar uma frase: "The issue needs to be addressed."', ARRAY['The', 'issue', 'needs', 'to', 'be', 'addressed']::text[], 'The issue needs to be addressed', 'A ordem correta é "The issue needs to be addressed.".', 'Need to be addressed é uma construção passiva comum.'),
    ('B2', 10, 'Organize as palavras para formar uma frase: "She came up with an elegant solution."', ARRAY['She', 'came', 'up', 'with', 'an', 'elegant', 'solution']::text[], 'She came up with an elegant solution', 'A ordem correta é "She came up with an elegant solution.".', 'Come up with significa criar ou encontrar uma ideia.'),
    ('B2', 11, 'Organize as palavras para formar uma frase: "We are on the verge of success."', ARRAY['We', 'are', 'on', 'the', 'verge', 'of', 'success']::text[], 'We are on the verge of success', 'A ordem correta é "We are on the verge of success.".', 'On the verge of indica que algo está prestes a acontecer.'),
    ('B2', 12, 'Organize as palavras para formar uma frase: "The figures do not add up."', ARRAY['The', 'figures', 'do', 'not', 'add', 'up']::text[], 'The figures do not add up', 'A ordem correta é "The figures do not add up.".', 'Add up significa fazer sentido ou totalizar corretamente.'),
    ('B2', 13, 'Organize as palavras para formar uma frase: "He denied having leaked the information."', ARRAY['He', 'denied', 'having', 'leaked', 'the', 'information']::text[], 'He denied having leaked the information', 'A ordem correta é "He denied having leaked the information.".', 'Deny é seguido por verbo com -ing; having marca anterioridade.'),
    ('B2', 14, 'Organize as palavras para formar uma frase: "This approach is bound to fail."', ARRAY['This', 'approach', 'is', 'bound', 'to', 'fail']::text[], 'This approach is bound to fail', 'A ordem correta é "This approach is bound to fail.".', 'Be bound to indica forte certeza.'),
    ('B2', 15, 'Organize as palavras para formar uma frase: "I am inclined to agree with you."', ARRAY['I', 'am', 'inclined', 'to', 'agree', 'with', 'you']::text[], 'I am inclined to agree with you', 'A ordem correta é "I am inclined to agree with you.".', 'Inclined to expressa uma tendência ou opinião.'),
    ('B2', 16, 'Organize as palavras para formar uma frase: "The project was completed ahead of schedule."', ARRAY['The', 'project', 'was', 'completed', 'ahead', 'of', 'schedule']::text[], 'The project was completed ahead of schedule', 'A ordem correta é "The project was completed ahead of schedule.".', 'Ahead of schedule significa antes do prazo previsto.'),
    ('B2', 17, 'Organize as palavras para formar uma frase: "It remains to be seen whether it works."', ARRAY['It', 'remains', 'to', 'be', 'seen', 'whether', 'it', 'works']::text[], 'It remains to be seen whether it works', 'A ordem correta é "It remains to be seen whether it works.".', 'Remains to be seen indica algo ainda incerto.'),
    ('B2', 18, 'Organize as palavras para formar uma frase: "We should bear in mind the deadline."', ARRAY['We', 'should', 'bear', 'in', 'mind', 'the', 'deadline']::text[], 'We should bear in mind the deadline', 'A ordem correta é "We should bear in mind the deadline.".', 'Bear in mind significa ter em mente.'),
    ('B2', 19, 'Organize as palavras para formar uma frase: "The report sheds light on the problem."', ARRAY['The', 'report', 'sheds', 'light', 'on', 'the', 'problem']::text[], 'The report sheds light on the problem', 'A ordem correta é "The report sheds light on the problem.".', 'Shed light on significa esclarecer.'),
