    ('C1', 5, 'Organize as palavras para formar uma frase: "The decision was met with widespread criticism."', ARRAY['The', 'decision', 'was', 'met', 'with', 'widespread', 'criticism']::text[], 'The decision was met with widespread criticism', 'A ordem correta é "The decision was met with widespread criticism.".', 'Be met with descreve a reação a algo.'),
    ('C1', 6, 'Organize as palavras para formar uma frase: "We must take a nuanced view of the issue."', ARRAY['We', 'must', 'take', 'a', 'nuanced', 'view', 'of', 'the', 'issue']::text[], 'We must take a nuanced view of the issue', 'A ordem correta é "We must take a nuanced view of the issue.".', 'A nuanced view reconhece diferenças e complexidade.'),
    ('C1', 7, 'Organize as palavras para formar uma frase: "The claim does not stand up to scrutiny."', ARRAY['The', 'claim', 'does', 'not', 'stand', 'up', 'to', 'scrutiny']::text[], 'The claim does not stand up to scrutiny', 'A ordem correta é "The claim does not stand up to scrutiny.".', 'Stand up to scrutiny significa resistir a uma análise cuidadosa.'),
