    ('C1', 9, 'Organize as palavras para formar uma frase: "The argument hinges on one assumption."', ARRAY['The', 'argument', 'hinges', 'on', 'one', 'assumption']::text[], 'The argument hinges on one assumption', 'A ordem correta é "The argument hinges on one assumption.".', 'Hinge on significa depender de algo central.'),
    ('C1', 10, 'Organize as palavras para formar uma frase: "This raises serious ethical concerns."', ARRAY['This', 'raises', 'serious', 'ethical', 'concerns']::text[], 'This raises serious ethical concerns', 'A ordem correta é "This raises serious ethical concerns.".', 'Raise concerns significa provocar ou apresentar preocupações.'),
    ('C1', 11, 'Organize as palavras para formar uma frase: "The distinction is far from trivial."', ARRAY['The', 'distinction', 'is', 'far', 'from', 'trivial']::text[], 'The distinction is far from trivial', 'A ordem correta é "The distinction is far from trivial.".', 'Far from trivial enfatiza que algo é importante.'),
    ('C1', 12, 'Organize as palavras para formar uma frase: "The evidence is open to interpretation."', ARRAY['The', 'evidence', 'is', 'open', 'to', 'interpretation']::text[], 'The evidence is open to interpretation', 'A ordem correta é "The evidence is open to interpretation.".', 'Open to interpretation indica que pode ser entendido de mais de uma forma.'),
