    ('C2', 2, 'Organize as palavras para formar uma frase: "The evidence lends credence to her account."', ARRAY['The', 'evidence', 'lends', 'credence', 'to', 'her', 'account']::text[], 'The evidence lends credence to her account', 'A ordem correta é "The evidence lends credence to her account.".', 'Lend credence to significa dar credibilidade.'),
    ('C2', 3, 'Organize as palavras para formar uma frase: "His remarks were open to misinterpretation."', ARRAY['His', 'remarks', 'were', 'open', 'to', 'misinterpretation']::text[], 'His remarks were open to misinterpretation', 'A ordem correta é "His remarks were open to misinterpretation.".', 'Open to misinterpretation indica risco de entendimento equivocado.'),
    ('C2', 4, 'Organize as palavras para formar uma frase: "The outcome was contingent on external factors."', ARRAY['The', 'outcome', 'was', 'contingent', 'on', 'external', 'factors']::text[], 'The outcome was contingent on external factors', 'A ordem correta é "The outcome was contingent on external factors.".', 'Contingent on significa dependente de uma condição.'),
    ('C2', 5, 'Organize as palavras para formar uma frase: "The report offers a cogent critique of the policy."', ARRAY['The', 'report', 'offers', 'a', 'cogent', 'critique', 'of', 'the', 'policy']::text[], 'The report offers a cogent critique of the policy', 'A ordem correta é "The report offers a cogent critique of the policy.".', 'Cogent descreve um argumento claro e convincente.'),
    ('C2', 6, 'Organize as palavras para formar uma frase: "The distinction is by no means clear cut."', ARRAY['The', 'distinction', 'is', 'by', 'no', 'means', 'clear', 'cut']::text[], 'The distinction is by no means clear cut', 'A ordem correta é "The distinction is by no means clear cut.".', 'By no means reforça uma negação.'),
    ('C2', 7, 'Organize as palavras para formar uma frase: "The theory is predicated on a false assumption."', ARRAY['The', 'theory', 'is', 'predicated', 'on', 'a', 'false', 'assumption']::text[], 'The theory is predicated on a false assumption', 'A ordem correta é "The theory is predicated on a false assumption.".', 'Be predicated on significa basear-se em algo.'),
    ('C2', 8, 'Organize as palavras para formar uma frase: "The findings shed unprecedented light on the issue."', ARRAY['The', 'findings', 'shed', 'unprecedented', 'light', 'on', 'the', 'issue']::text[], 'The findings shed unprecedented light on the issue', 'A ordem correta é "The findings shed unprecedented light on the issue.".', 'Unprecedented significa sem precedente ou nunca visto.'),
    ('C2', 9, 'Organize as palavras para formar uma frase: "Her explanation was conspicuously vague."', ARRAY['Her', 'explanation', 'was', 'conspicuously', 'vague']::text[], 'Her explanation was conspicuously vague', 'A ordem correta é "Her explanation was conspicuously vague.".', 'Conspicuously destaca algo notavelmente perceptível.'),
    ('C2', 10, 'Organize as palavras para formar uma frase: "The compromise proved to be untenable."', ARRAY['The', 'compromise', 'proved', 'to', 'be', 'untenable']::text[], 'The compromise proved to be untenable', 'A ordem correta é "The compromise proved to be untenable.".', 'Untenable descreve algo impossível de manter ou defender.'),
    ('C2', 11, 'Organize as palavras para formar uma frase: "The wording is deliberately ambiguous."', ARRAY['The', 'wording', 'is', 'deliberately', 'ambiguous']::text[], 'The wording is deliberately ambiguous', 'A ordem correta é "The wording is deliberately ambiguous.".', 'Deliberately indica intenção; ambiguous permite mais de uma leitura.'),
    ('C2', 12, 'Organize as palavras para formar uma frase: "The argument is predicated on a spurious comparison."', ARRAY['The', 'argument', 'is', 'predicated', 'on', 'a', 'spurious', 'comparison']::text[], 'The argument is predicated on a spurious comparison', 'A ordem correta é "The argument is predicated on a spurious comparison.".', 'Spurious descreve algo falso, mas aparentemente convincente.'),
    ('C2', 13, 'Organize as palavras para formar uma frase: "The minister sought to allay public concern."', ARRAY['The', 'minister', 'sought', 'to', 'allay', 'public', 'concern']::text[], 'The minister sought to allay public concern', 'A ordem correta é "The minister sought to allay public concern.".', 'Allay concern significa reduzir uma preocupação.'),
    ('C2', 14, 'Organize as palavras para formar uma frase: "The decision has far reaching implications."', ARRAY['The', 'decision', 'has', 'far', 'reaching', 'implications']::text[], 'The decision has far reaching implications', 'A ordem correta é "The decision has far reaching implications.".', 'Far-reaching descreve efeitos amplos e duradouros.'),
    ('C2', 15, 'Organize as palavras para formar uma frase: "The account is not entirely devoid of merit."', ARRAY['The', 'account', 'is', 'not', 'entirely', 'devoid', 'of', 'merit']::text[], 'The account is not entirely devoid of merit', 'A ordem correta é "The account is not entirely devoid of merit.".', 'Devoid of significa sem algo; merit é valor ou qualidade.'),
    ('C2', 16, 'Organize as palavras para formar uma frase: "The findings run counter to conventional wisdom."', ARRAY['The', 'findings', 'run', 'counter', 'to', 'conventional', 'wisdom']::text[], 'The findings run counter to conventional wisdom', 'A ordem correta é "The findings run counter to conventional wisdom.".', 'Run counter to significa contrariar uma expectativa ou crença.'),
    ('C2', 17, 'Organize as palavras para formar uma frase: "She articulated a compelling rationale for reform."', ARRAY['She', 'articulated', 'a', 'compelling', 'rationale', 'for', 'reform']::text[], 'She articulated a compelling rationale for reform', 'A ordem correta é "She articulated a compelling rationale for reform.".', 'Rationale é a razão ou lógica por trás de uma decisão.'),
    ('C2', 18, 'Organize as palavras para formar uma frase: "The distinction is subtle yet consequential."', ARRAY['The', 'distinction', 'is', 'subtle', 'yet', 'consequential']::text[], 'The distinction is subtle yet consequential', 'A ordem correta é "The distinction is subtle yet consequential.".', 'Yet conecta contraste; consequential significa com efeitos importantes.'),
