insert into public.questions (
  lesson_id, question_type, prompt, choices, sort_order, difficulty, is_published
)
select lessons.id, 'word_order', word_questions.prompt, to_jsonb(word_questions.words),
  word_questions.question_order, 'intermediate', true
from word_questions
join public.lessons
  on lessons.slug = 'organize-' || lower(word_questions.level_code)
on conflict (lesson_id, sort_order) do update set
  question_type = excluded.question_type,
  prompt = excluded.prompt,
  choices = excluded.choices,
  difficulty = excluded.difficulty,
  is_published = excluded.is_published;

with word_questions(level_code, question_order, prompt, words, answer, explanation, hint) as (
  values
    ('A1', 1, 'Organize as palavras para formar uma frase: "I am a student."', ARRAY['I', 'am', 'a', 'student']::text[], 'I am a student', 'A ordem correta é "I am a student.".', 'Use am com I para falar de identidade, profissão e estado.'),
