    ('A1', 7, 'Organize as palavras para formar uma frase: "He works at home."', ARRAY['He', 'works', 'at', 'home']::text[], 'He works at home', 'A ordem correta é "He works at home.".', 'Use works com he; at home indica o local da atividade.'),
    ('A1', 8, 'Organize as palavras para formar uma frase: "We live in Brazil."', ARRAY['We', 'live', 'in', 'Brazil']::text[], 'We live in Brazil', 'A ordem correta é "We live in Brazil.".', 'Use live in para falar onde alguém mora.'),
    ('A1', 9, 'Organize as palavras para formar uma frase: "What is your name."', ARRAY['What', 'is', 'your', 'name']::text[], 'What is your name', 'A ordem correta é "What is your name.".', 'What is your name? é uma pergunta básica para conhecer alguém.'),
    ('A1', 10, 'Organize as palavras para formar uma frase: "How are you today."', ARRAY['How', 'are', 'you', 'today']::text[], 'How are you today', 'A ordem correta é "How are you today.".', 'How are you? pergunta como a pessoa está.'),
