    ('A1', 12, 'Organize as palavras para formar uma frase: "She is from Spain."', ARRAY['She', 'is', 'from', 'Spain']::text[], 'She is from Spain', 'A ordem correta é "She is from Spain.".', 'Use is from para falar de origem.'),
    ('A1', 13, 'Organize as palavras para formar uma frase: "They are at school."', ARRAY['They', 'are', 'at', 'school']::text[], 'They are at school', 'A ordem correta é "They are at school.".', 'Use at para indicar um ponto ou lugar específico.'),
    ('A1', 14, 'Organize as palavras para formar uma frase: "It is sunny today."', ARRAY['It', 'is', 'sunny', 'today']::text[], 'It is sunny today', 'A ordem correta é "It is sunny today.".', 'Use it is para falar sobre o clima.'),
    ('A1', 15, 'Organize as palavras para formar uma frase: "I wake up early."', ARRAY['I', 'wake', 'up', 'early']::text[], 'I wake up early', 'A ordem correta é "I wake up early.".', 'Wake up significa acordar; early significa cedo.'),
    ('A1', 16, 'Organize as palavras para formar uma frase: "He drinks water."', ARRAY['He', 'drinks', 'water']::text[], 'He drinks water', 'A ordem correta é "He drinks water.".', 'Com he, drink vira drinks no presente.'),
    ('A1', 17, 'Organize as palavras para formar uma frase: "Can I have water."', ARRAY['Can', 'I', 'have', 'water']::text[], 'Can I have water', 'A ordem correta é "Can I have water.".', 'Can I have...? é uma forma educada de pedir algo.'),
