    ('A2', 13, 'Organize as palavras para formar uma frase: "I have to leave now."', ARRAY['I', 'have', 'to', 'leave', 'now']::text[], 'I have to leave now', 'A ordem correta é "I have to leave now.".', 'Have to expressa necessidade ou obrigação.'),
    ('A2', 14, 'Organize as palavras para formar uma frase: "You should get some rest."', ARRAY['You', 'should', 'get', 'some', 'rest']::text[], 'You should get some rest', 'A ordem correta é "You should get some rest.".', 'Should dá conselhos.'),
    ('A2', 15, 'Organize as palavras para formar uma frase: "I used to live there."', ARRAY['I', 'used', 'to', 'live', 'there']::text[], 'I used to live there', 'A ordem correta é "I used to live there.".', 'Used to fala de hábitos ou situações passadas.'),
    ('A2', 16, 'Organize as palavras para formar uma frase: "She has been working all day."', ARRAY['She', 'has', 'been', 'working', 'all', 'day']::text[], 'She has been working all day', 'A ordem correta é "She has been working all day.".', 'Present perfect continuous destaca duração até agora.'),
    ('A2', 17, 'Organize as palavras para formar uma frase: "We missed the bus."', ARRAY['We', 'missed', 'the', 'bus']::text[], 'We missed the bus', 'A ordem correta é "We missed the bus.".', 'Missed significa perdeu; use também para encontros ou pessoas.'),
    ('A2', 18, 'Organize as palavras para formar uma frase: "Could I make a reservation."', ARRAY['Could', 'I', 'make', 'a', 'reservation']::text[], 'Could I make a reservation', 'A ordem correta é "Could I make a reservation.".', 'Could I...? é útil em hotéis e restaurantes.'),
