    ('C2', 19, 'Organize as palavras para formar uma frase: "The policy is liable to exacerbate inequality."', ARRAY['The', 'policy', 'is', 'liable', 'to', 'exacerbate', 'inequality']::text[], 'The policy is liable to exacerbate inequality', 'A ordem correta é "The policy is liable to exacerbate inequality.".', 'Liable to indica probabilidade; exacerbate significa piorar.'),
    ('C2', 20, 'Organize as palavras para formar uma frase: "The conclusion is not borne out by the evidence."', ARRAY['The', 'conclusion', 'is', 'not', 'borne', 'out', 'by', 'the', 'evidence']::text[], 'The conclusion is not borne out by the evidence', 'A ordem correta é "The conclusion is not borne out by the evidence.".', 'Be borne out by significa ser confirmado por evidências.')
)
insert into public.question_answers (question_id, accepted_answers, explanation, hint)
select questions.id, array[word_questions.answer], word_questions.explanation, word_questions.hint
from word_questions
join public.lessons
  on lessons.slug = 'organize-' || lower(word_questions.level_code)
join public.questions
  on questions.lesson_id = lessons.id
 and questions.sort_order = word_questions.question_order
on conflict (question_id) do update set
  accepted_answers = excluded.accepted_answers,
  explanation = excluded.explanation,
  hint = excluded.hint;

drop view if exists public.published_lesson_questions;
create view public.published_lesson_questions
with (security_barrier = true)
as
  select
    lessons.id as lesson_id,
    lessons.slug as lesson_slug,
    lessons.title as lesson_title,
    lessons.description as lesson_description,
    lessons.category as lesson_category,
    lessons.duration_minutes,
    lessons.sort_order as lesson_sort_order,
    language_levels.code as level_code,
    language_levels.title as level_title,
    questions.id as question_id,
    questions.question_type,
    questions.prompt,
    questions.choices,
    questions.audio_path,
    questions.sort_order as question_sort_order,
    questions.difficulty,
    question_answers.hint
  from public.lessons
  join public.language_levels on language_levels.id = lessons.level_id
  join public.questions on questions.lesson_id = lessons.id
  left join public.question_answers on question_answers.question_id = questions.id
  where lessons.is_published and questions.is_published;

grant select on public.published_lesson_questions to anon, authenticated;

commit;

